    public static class ClaudeLéviStrauss
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Le péché originel de l'anthropologie consiste dans la confusion entre la notion purement biologique de race (à supposer, d'ailleurs, que, même sur ce terrain limité, cette notion puisse prétendre à l'objectivité, ce que la génétique moderne conteste) et les productions sociologiques et psychologiques des cultures humaines.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "[L'humanité] ne se développe pas sous le régime d'une uniforme monotonie, mais à travers des modes extraordinairement diversifiés de sociétés et de civilisations ; cette diversité intellectuelle, esthétique, sociologique, n'est unie par aucune relation de cause à effet à celle qui existe, sur le plan biologique, entre certains aspects observables des groupements humains ; elle lui est seulement parallèle sur un autre terrain.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Le barbare, c'est d'abord l'homme qui croit à la barbarie.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "La simple proclamation de l'égalité naturelle entre tous les hommes et de la fraternité qui doit les unir, sans distinction de races ou de cultures, a quelque chose de décevant pour l'esprit, parce qu'elle néglige une diversité de fait, qui s'oppose à l'observation et dont il ne suffit pas de dire qu'elle n'affecte pas le fond du problème pour que l'on soit théoriquement et pratiquement autorisé à faire comme si elle n'existait pas.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Les anciens chinois, les Eskimos, avaient poussé très loin les arts mécaniques ; et il s'en est fallu de fort peu qu'ils n'arrivent au point où la « réaction en chaîne » se déclenche, déterminant le passage d'un type de civilisation à l'autre.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "La civilisation mondiale ne saurait être autre chose que la coalition de cultures, préservant chacune son originalité.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "La tolérance n'est pas une position contemplative, dispensant les indulgences à ce qui fut ou à ce qui est. C'est une attitude dynamique, qui consiste à prévoir, à comprendre et à promouvoir ce qui veut être.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "La diversité des cultures est derrière nous, autour de nous et devant nous. La seule exigence que nous puissions faire valoir à son endroit (créatrice pour chaque individu des devoirs correspondants) est qu'elle se réalise sous des formes dont chacune soit une contribution à la plus grande générosité des autres.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Je hais les voyages et les explorateurs.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "L'humanité s'installe dans la mono-culture ; elle s'apprête à produire la civilisation en masse, comme la betterave. Son ordinaire ne comportera plus que ce plat.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Moins les cultures humaines étaient en mesure de communiquer entre elles et donc de se corrompre par leur contact, moins aussi leurs émissaires respectifs étaient capables de percevoir la richesse et la signification de cette diversité.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Tout problème, grave ou futile, peut être liquidé par l'application d'une méthode, toujours identique, qui consiste à opposer deux vues traditionnelles de la question ; à introduire la première par les justifications du sens commun, puis à les détruire au moyen de la seconde ; enfin à les renvoyer dos à dos grâce à une troisième qui révèle le caractère également partiel des deux autres, ramenés par des artifices de vocabulaire aux aspects complèmentaires d'une même réalité: forme et fond, contenant et contenu, être et paraître, continu et discontu, essence et existence, etc.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Un voyage s'inscrit simultanément dans l'espace, dans le temps, et dans la hiérarchie sociale. Chaque impression n'est définissable qu'en les rapportant solidairement à ces trois axes, et comme l'espace possède à lui seul trois dimensions, il en faudrait au moins cinq pour se faire du voyage une représentation adéquate.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Ce que nous nommons exotisme traduit une inégalité de rythme, significative pendant le laps de quelques siècles et voilant provisoirement un destin qui aurait bien pu demeurer solidaire.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "La liberté n'est ni une invention juridique ni un trésor philosophique, propriété chérie de civilisations plus dignes que d'autres parce qu'elles seules sauraient la produire ou la préserver. Elle résulte d'une relation objective entre l'individu et l'espace qu'il occupe, entre le consommateur et les ressources dont il dispose.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Il faut beaucoup de naïveté ou de mauvaise foi pour penser que les hommes choisissent leurs croyances indépendamment de leur condition.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Ce n’est pas seulement pour duper nos enfants que nous les entretenons dans la croyance au Père Noël : leur ferveur nous réchauffe, nous aide à nous tromper nous-mêmes et à croire, puisqu’ils y croient, qu’un monde de générosité sans contrepartie n’est pas absolument incompatible avec la réalité. Et pourtant, les hommes meurent, ils ne reviennent jamais ; et tout ordre social se rapproche de la mort, en ce sens qu’il prélève quelque chose contre quoi il ne donne pas d’équivalent.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "Le monde a commencé sans l’homme et il s’achèvera sans lui. Les institutions, les mœurs et les coutumes, que j’aurai passé ma vie à inventorier et à comprendre, sont une efflorescence passagère d’une création par rapport à laquelle elles ne possèdent aucun sens, sinon peut-être de permettre à l’humanité d’y jouer son rôle. Loin que ce rôle lui marque une place indépendante et que l’effort de l’homme – même condamné – soit de s’opposer vainement à une déchéance universelle, il apparaît lui-même comme une machine, peut-être plus perfectionnée que les autres, travaillant à la désagrégation d’un ordre originel et précipitant une matière puissamment organisée vers une inertie toujours plus grande et qui sera un jour définitive.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "On comprend enfin que les espèces naturelles ne sont pas choisies parce que \"bonnes à manger\" mais parce que \"bonnes à penser\".", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "En ce siècle où l’homme s’acharne à détruire d’innombrables formes vivantes, après tant de siècles dont la richesse et la diversité constituaient de temps immémorial, le plus clair de son patrimoine, jamais sans doute, il n’a été plus nécessaire de dire, comme le font les mythes, qu’un humanisme bien ordonné, ne commence pas par soi-même, mais place le monde avant la vie, la vie avant l’homme, le respect des autres avant l’amour-propre : et que même un séjour d’un ou deux millions d’années sur cette terre, puisque de toute façon il connaîtra un terme, ne saurait servir d’excuse à une espèce quelconque, fût-ce la nôtre, pour se l’approprier comme une chose et s’y conduire sans pudeur ni discrétion.", Author = "Claude Lévi-Strauss" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Lévi-Strauss", Text = "On a mis dans la tête des gens que la société relevait de la pensée abstraite alors qu'elle est faite d'habitudes, d'usages, et qu'en broyant ceux-ci sous les meules de la raison, on pulvérise des genres de vie fondés sur une longue tradition, on réduit les individus à l'état d'atomes interchangeables et anonymes. La liberté véritable ne peut avoir qu'un contenu concret : elle est faite d'équilibres entre de petites appartenances, de menues solidarités : ce contre quoi les idées théoriques qu'on proclame rationnelles s'acharnent ; quand elles sont parvenues à leurs fins, il ne reste plus qu'à s'entre-détruire.", Author = "Claude Lévi-Strauss" },
        };
    }
